A = np.array([float(x) for x in A_raw])
B = np.array([float(x) for x in B_raw])

diff = A - B

print("Sizes:", len(A), len(B))

print("Mean diff:", np.mean(diff))
print("Median diff:", np.median(diff))
print("Std diff:", np.std(diff, ddof=1))

plt.hist(diff, bins=30)
plt.xlabel("A - B")
plt.ylabel("Count")
plt.show()

# Paired t-test
result = ttest_rel(A, B)

print("t-statistic:", result.statistic)
print("p-value:", result.pvalue)

# Effect size (mean paired difference)
diff = A - B
print("Mean difference (A-B):", np.mean(diff))
print("Median difference (A-B):", np.median(diff))

res = wilcoxon(A, B, alternative="less")
print("Wilcoxon p-value:", res.pvalue)